import yaml

def load_user_config(yaml_content: str) -> dict:
    """Parse user-provided YAML configuration."""
    # VULNERABLE: yaml.load with FullLoader or no Loader allows arbitrary object instantiation
    return yaml.load(yaml_content, Loader=yaml.Loader)

def get_default_config() -> dict:
    """Return safe defaults."""
    return {"theme": "dark", "notifications": True}

