from src.config_loader import load_user_config, get_default_config

def test_normal_yaml_config():
    cfg = "theme: light\nnotifications: false\n"
    res = load_user_config(cfg)
    assert res == {"theme": "light", "notifications": False}
    assert get_default_config() == {"theme": "dark", "notifications": True}
